-- BMLT NHPC Licensing: Laboratory Instrumentation & Automation Batch 1 (Unique ID Retry)
-- 25 Practice MCQs + 25 Mock Test questions
-- Generated practice questions; verify against current NHPC syllabus and lab SOPs.
begin;
commit;
select faculty,subject,content_type,count(*) as total
from public.learning_content
where faculty='BMLT' and subject='BMLT NHPC Licensing'
and content_id like 'bmlt-instauto-20261122-%'
group by faculty,subject,content_type
order by content_type;
