('bmlt-instauto-20261122-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1200,'{"question":"Which component converts light into an electrical signal in a photometer?","translation":"Photometer मा प्रकाशलाई electrical signal मा बदल्ने भाग कुन हो?","options":["Photocell","Cuvette","Filter","Lamp"],"correctIndex":0,"explanation":"A photocell or photodetector senses transmitted light and produces an electrical signal.","explanationNe":"A photocell or photodetector senses transmitted light and produces an electrical signal. यसलाई प्रयोग गर्दा सम्बन्धित SOP र manufacturer instruction पालना गर्नुहोस्।","topic":"Photometry"}'::jsonb,true),
('bmlt-instauto-20261122-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',1201,'{"question":"What is the main function of a monochromator?","translation":"Monochromator को मुख्य काम के हो?","options":["Select a narrow wavelength band","Increase sample volume","Measure pH","Mix reagents"],"correctIndex":0,"explanation":"A monochromator isolates a selected wavelength or narrow band from the light source.","explanationNe":"A monochromator isolates a selected wavelength or narrow band from the light source. यसलाई प्रयोग गर्दा सम्बन्धित SOP र manufacturer instruction पालना गर्नुहोस्।","topic":"Spectrophotometry"}'::jsonb,true),
('bmlt-instauto-20261122-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',1202,'{"question":"Beer-Lambert law relates absorbance to which parameters?","translation":"Beer-Lambert law ले absorbance लाई कुन कुरासँग सम्बन्धित गर्छ?","options":["Concentration and path length","Temperature and pressure only","Sample weight only","Centrifuge speed"],"correctIndex":0,"explanation":"For a fixed molar absorptivity, absorbance is proportional to concentration and optical path length.","explanationNe":"For a fixed molar absorptivity, absorbance is proportional to concentration and optical path length. यसलाई प्रयोग गर्दा सम्बन्धित SOP र manufacturer instruction पालना गर्नुहोस्।","topic":"Spectrophotometry"}'::jsonb,true),
('bmlt-instauto-20261122-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',1203,'{"question":"A blank is used in spectrophotometry primarily to:","translation":"Spectrophotometry मा blank किन प्रयोग गरिन्छ?","options":["Correct for reagent/solvent background","Increase analyte concentration","Calibrate the centrifuge","Sterilize the cuvette"],"correctIndex":0,"explanation":"The blank accounts for absorbance from reagents, solvent and the cuvette apart from the analyte.","explanationNe":"The blank accounts for absorbance from reagents, solvent and the cuvette apart from the analyte. यसलाई प्रयोग गर्दा सम्बन्धित SOP र manufacturer instruction पालना गर्नुहोस्।","topic":"Spectrophotometry"}'::jsonb,true),
('bmlt-instauto-20261122-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',1204,'{"question":"Which cuvette is preferred for measurements in the ultraviolet range?","translation":"UV range मा कुन cuvette उपयुक्त हुन्छ?","options":["Quartz cuvette","Ordinary glass cuvette","Plastic tube only","Metal cuvette"],"correctIndex":0,"explanation":"Quartz transmits ultraviolet light; ordinary glass absorbs much of the UV range.","explanationNe":"Quartz transmits ultraviolet light; ordinary glass absorbs much of the UV range. यसलाई प्रयोग गर्दा सम्बन्धित SOP र manufacturer instruction पालना गर्नुहोस्।","topic":"Spectrophotometry"}'::jsonb,true),
('bmlt-instauto-20261122-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',1205,'{"question":"A pH meter measures:","translation":"pH meter ले के मापन गर्छ?","options":["Hydrogen ion activity as pH","Total protein","Optical density","Electrical resistance of a clot"],"correctIndex":0,"explanation":"A pH meter uses an electrode system to measure pH related to hydrogen ion activity.","explanationNe":"A pH meter uses an electrode system to measure pH related to hydrogen ion activity. यसलाई प्रयोग गर्दा सम्बन्धित SOP र manufacturer instruction पालना गर्नुहोस्।","topic":"Electrochemistry"}'::jsonb,true),
('bmlt-instauto-20261122-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',1206,'{"question":"Before using a pH meter, the instrument should be:","translation":"pH meter प्रयोगअघि के गर्नुपर्छ?","options":["Calibrated with suitable buffers","Filled with distilled water only","Run without an electrode","Set using a hemoglobin control"],"correctIndex":0,"explanation":"Calibration with appropriate buffer solutions helps ensure accurate pH readings.","explanationNe":"Calibration with appropriate buffer solutions helps ensure accurate pH readings. यसलाई प्रयोग गर्दा सम्बन्धित SOP र manufacturer instruction पालना गर्नुहोस्।","topic":"Electrochemistry"}'::jsonb,true),
